create or replace function private.signal_leaderboard_update() returns trigger language plpgsql security definer set search_path='' as $$begin update public.leaderboard_updates set revision=revision+1,updated_at=clock_timestamp() where division in ('owner','vivid_life','legacy_life');return null;end $$;

do $$declare v_sale uuid;v_before bigint;begin begin perform set_config('request.jwt.claims',jsonb_build_object('sub','8139e230-055d-4247-8133-684ed817b4fa','role','authenticated','aal','aal2')::text,true);set local role authenticated;select revision into v_before from public.leaderboard_updates where division='vivid_life';v_sale:=public.chat_standalone_deal('vivid_life','8139e230-055d-4247-8133-684ed817b4fa',gen_random_uuid(),'Verification','Term',100,(now() at time zone 'America/Detroit')::date);if not exists(select 1 from public.chat_messages where source_deal_id=v_sale) then raise exception 'Missing deal card';end if;if (select revision from public.leaderboard_updates where division='vivid_life')<=v_before then raise exception 'Missing leaderboard signal';end if;raise exception using errcode='ZX001',message='Rollback verification sale';exception when sqlstate 'ZX001' then null;end;end $$;
